function makeDealer(){box(34,.18,32,0xb9bec3,-25,.02,25);box(32,6,10,0x28547a,-25,3,35);box(34,.5,12,0xf4b52e,-25,6.2,35);addCollider(-25,35,33,11);const postMat=mat(0xf4b52e);[-40,-10].forEach(x=>scene.add(part(new T.BoxGeometry(.35,4,.35),postMat,x,2,27)));const signCanvas=document.createElement('canvas');signCanvas.width=1024;signCanvas.height=256;const ctx=signCanvas.getContext('2d');ctx.fillStyle='#173552';ctx.fillRect(0,0,1024,256);ctx.strokeStyle='#f8c746';ctx.lineWidth=22;ctx.strokeRect(11,11,1002,234);ctx.fillStyle='#fff';ctx.font='900 92px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('LOJA DE VEÍCULOS',512,128);const sign=part(new T.PlaneGeometry(18,4.5),new T.MeshBasicMaterial({map:new T.CanvasTexture(signCanvas)}),-25,4.1,29.94);scene.add(sign)}
function makePortal(x,z,id,target,label,color=0x70e8ff){const g=new T.Group(),ring=part(new T.TorusGeometry(1.85,.2,12,34),mat(color,{emissive:color,emissiveIntensity:1.7}),0,2.15,0),outer=part(new T.TorusGeometry(2.18,.08,10,34),mat(0xffffff,{emissive:color,emissiveIntensity:1}),0,2.15,.01),light=part(new T.CircleGeometry(1.72,34),new T.MeshBasicMaterial({color,transparent:true,opacity:.42,side:T.DoubleSide}),0,2.15,.03),star=part(new T.OctahedronGeometry(.38),mat(0xffe76b,{emissive:0xffb400,emissiveIntensity:1.8}),0,4.75,0);g.add(ring,outer,light,star,part(new T.BoxGeometry(.58,2.2,.65),mat(0x435c69),-1.85,1.05,0),part(new T.BoxGeometry(.58,2.2,.65),mat(0x435c69),1.85,1.05,0));[-1.15,-.55,0,.55,1.15].forEach((px,i)=>g.add(part(new T.SphereGeometry(.09,8,6),mat(i%2?0xffffff:color,{emissive:color,emissiveIntensity:1.7}),px,4.05-Math.abs(px)*.35,.06)));g.position.set(x,0,z);g.userData={id,target,label,ring,outer,light,star};portals.push(g);scene.add(g);return g}
function makeFarmAnimal(kind,x,z,color){const g=new T.Group(),body=part(new T.SphereGeometry(.72,12,9),mat(color),0,.85,0),head=part(new T.SphereGeometry(.42,12,9),mat(color),0,1.22,.62);body.scale.set(1.2,.78,.8);g.add(body,head);[-.42,.42].forEach(px=>[-.25,.25].forEach(pz=>g.add(part(new T.CylinderGeometry(.09,.11,.65,7),mat(color),px,.34,pz))));const label=kind==='Vaca'?'🐄':kind==='Galinha'?'🐔':'🐑',index=farmAnimals.length;g.add(part(new T.SphereGeometry(.13,8,6),mat(0xffffff),-.16,1.32,.96),part(new T.SphereGeometry(.13,8,6),mat(0xffffff),.16,1.32,.96));g.position.set(x,0,z);g.userData={kind,label,index,fed:farmState.fedAnimals.includes(index),phase:index*1.8};farmAnimals.push(g);scene.add(g)}
function makeFarmStation(type,x,z,color){const g=new T.Group(),base=part(new T.CylinderGeometry(4,4.8,.45,12),mat(color),0,.23,0),sign=part(new T.BoxGeometry(5.5,3.2,.3),mat(0xf4e4ad),0,3,0);g.add(base,sign);for(let i=0;i<4;i++)g.add(part(new T.BoxGeometry(1.2,1.2,1.2),mat(type==='load'?0xe7b84d:0x72c8e8),-1.8+i*1.2,1,-.5+(i%2)));g.position.set(x,0,z);g.userData={type};farmStations.push(g);scene.add(g)}
