function makeDinoFigure(x,z,color=0x54b66a){const g=new T.Group(),body=part(new T.SphereGeometry(1.5,14,10),mat(color),0,1.5,0),head=part(new T.SphereGeometry(.85,12,9),mat(color),0,3.2,1.35),neck=part(new T.CylinderGeometry(.35,.65,2.2,10),mat(color),0,2.35,.72),tail=part(new T.ConeGeometry(.58,3.2,10),mat(color),0,1.45,-2.05);tail.rotation.x=-Math.PI/2;body.scale.set(1.25,.8,.82);g.add(body,head,neck,tail);[-.72,.72].forEach(px=>g.add(part(new T.CylinderGeometry(.24,.3,1.5,8),mat(color),px,.65,-.1)));g.position.set(x,0,z);scene.add(g);return g}
