function useAdventureAction(station){const {world,index}=station.userData,list=adventureState.tasks[world]??=[],stepKey=`${world}-${index}`;if(list.includes(index))return flash('✅ Esta tarefa já está concluída.');const step=Math.min(3,(adventureState.steps[stepKey]||0)+1);adventureState.steps[stepKey]=step;station.userData.marker.scale.setScalar(1+step*.12);if(step<3){flash(`🛠️ Tarefa em progresso: ${step}/3`);saveAdventures();hud();return}list.push(index);adventureState.tasks[world]=list;station.userData.done=true;station.children[0].material.color.setHex(0x4caf68);station.userData.marker.material.color.setHex(0x7cff9a);station.userData.marker.scale.setScalar(1);coins+=5;const complete=list.length>=worldTasks[world].length,rewardKey=`${world}-activities`;if(complete&&!adventureState.completed[rewardKey]){adventureState.completed[rewardKey]=true;coins+=30;typeof celebrate==='function'&&celebrate(true);flash(`🏆 ${adventureWorlds[world].label} concluído: +30 moedas!`)}else flash(`${worldTasks[world][index][1]} +5 moedas!`);saveGarage();saveAdventures();hud()}
