function startObbyRace(){if(activeVehicle&&activeVehicle!==obbyRace.kart){activeVehicle.userData.occupied=false;resetRider()}activeVehicle=obbyRace.kart;activeVehicle.userData.occupied=true;activeVehicle.position.set(adventureWorlds.obby.x,0,adventureWorlds.obby.z-165);activeVehicle.userData.heading=heading=Math.PI/2;activeVehicle.rotation.y=heading;player.visible=false;speed=0;obbyRace.running=true;obbyRace.finished=false;obbyRace.lap=1;obbyRace.checkpoint=0;obbyRace.startedAt=performance.now();obbyRivals.forEach((r,i)=>{r.userData.theta=-Math.PI/2-(i+1)*.075;r.userData.distance=-(i+1)*.075});flash('🏁 Corrida iniciada — 3 voltas!')}
function updateObbyRace(dt){if(currentWorld!=='obby')return;const cx=adventureWorlds.obby.x,cz=adventureWorlds.obby.z,rx=215,rz=165;obbyRivals.forEach(r=>{r.userData.distance+=dt*r.userData.speed/180;r.userData.theta+=dt*r.userData.speed/180;const a=r.userData.theta;r.position.set(cx+Math.cos(a)*rx,0,cz+Math.sin(a)*rz);r.rotation.y=Math.atan2(-rx*Math.sin(a),rz*Math.cos(a))});if(!obbyRace.running||activeVehicle!==obbyRace.kart)return;const angles=[0,Math.PI/2,Math.PI,-Math.PI/2],a=angles[obbyRace.checkpoint],px=cx+Math.cos(a)*rx,pz=cz+Math.sin(a)*rz;if(Math.hypot(activeVehicle.position.x-px,activeVehicle.position.z-pz)<13){obbyRace.checkpoint++;if(obbyRace.checkpoint>=4){obbyRace.checkpoint=0;if(obbyRace.lap>=3){obbyRace.running=false;obbyRace.finished=true;speed=0;coins+=50;saveGarage();typeof celebrate==='function'&&celebrate(true);flash('🏆 Venceste a corrida: +50 moedas!')}else{obbyRace.lap++;flash(`🏁 Volta ${obbyRace.lap}/3`)}}}const progress=((Math.atan2((activeVehicle.position.z-cz)/rz,(activeVehicle.position.x-cx)/rx)+Math.PI/2+Math.PI*2)%(Math.PI*2)),playerDistance=(obbyRace.lap-1)*Math.PI*2+progress;obbyRace.position=1+obbyRivals.filter(r=>r.userData.distance>playerDistance).length;const lane=Math.sqrt(((activeVehicle.position.x-cx)/rx)**2+((activeVehicle.position.z-cz)/rz)**2);if(Math.abs(lane-1)>.11)speed*=Math.pow(.12,dt);const now=performance.now();if(now>obbyRace.boostReadyAt&&obbyBoosts.some(b=>Math.hypot(activeVehicle.position.x-b.position.x,activeVehicle.position.z-b.position.z)<8)){speed=Math.min(activeVehicle.userData.max+10,speed+9);obbyRace.boostReadyAt=now+1200;flash('⚡ BOOST!')}}
