function updateDinoQuest(dt,now){if(currentWorld!=='dino'||dinoQuest.complete)return;const current=dinoQuest.footprints[dinoQuest.step];if(current&&Math.hypot(player.position.x-current.position.x,player.position.z-current.position.z)<3.5){current.material.color.setHex(0x61d579);dinoQuest.step++;if(dinoQuest.footprints[dinoQuest.step])dinoQuest.footprints[dinoQuest.step].visible=true;flash(dinoQuest.step===dinoQuest.footprints.length?'🦕 Encontraste o filhote! Aproxima-te dele.':`👣 Pegada ${dinoQuest.step}/${dinoQuest.footprints.length}`)}dinoQuest.eggs.forEach((egg,i)=>{if(!egg.visible)return;egg.rotation.y+=.025;egg.position.y=egg.userData.baseY+Math.sin(now*.004+egg.userData.phase)*.18;if(Math.hypot(player.position.x-egg.position.x,player.position.z-egg.position.z)<2.5){egg.visible=false;dinoQuest.eggCount++;coins+=2;saveGarage();typeof tone==='function'&&tone(760+i*35,.1);flash(`🥚 Ovo encontrado: ${dinoQuest.eggCount}/${dinoQuest.eggs.length}`)}});dinoQuest.predators.forEach(p=>{const patrol=p.userData.patrol,a=now*.00045+patrol.phase;p.position.x=patrol.x+Math.cos(a)*28;p.position.z=patrol.z+Math.sin(a)*22;p.rotation.y=-a;if(dinoQuest.following&&now>dinoQuest.lastScare&&Math.hypot(player.position.x-p.position.x,player.position.z-p.position.z)<6){dinoQuest.lastScare=now+2500;dinoQuest.following=false;dinoQuest.baby.position.set(dinoQuest.babyHome.x,0,dinoQuest.babyHome.z);flash('⚠️ Um dinossauro assustou o filhote. Volta a procurá-lo!')}});if(dinoQuest.following){const tx=player.position.x-Math.sin(heading)*2.8,tz=player.position.z-Math.cos(heading)*2.8;dinoQuest.baby.position.x+=(tx-dinoQuest.baby.position.x)*Math.min(1,dt*3.4);dinoQuest.baby.position.z+=(tz-dinoQuest.baby.position.z)*Math.min(1,dt*3.4);dinoQuest.baby.rotation.y=heading}}
