const toyNames=['CARRO','ROBÔ','COMBOIO','FOGUETÃO'];
function makeToyWorkshop(cx,cz){adventureState.toyParts=adventureState.toyParts&&typeof adventureState.toyParts==='object'?adventureState.toyParts:{};adventureState.toysBuilt=Array.isArray(adventureState.toysBuilt)?adventureState.toysBuilt:[];const padSpots=[[-145,-90],[145,-90],[-145,120],[145,120]],colors=[0xf05b58,0x58c8db,0x68c66c,0xffc947];padSpots.forEach((p,i)=>{const pad=part(new T.CylinderGeometry(8,9,.5,16),mat(colors[i],{emissive:colors[i],emissiveIntensity:.25}),cx+p[0],.25,cz+p[1]);pad.userData={project:i};toyQuest.pads.push(pad);scene.add(pad)});for(let project=0;project<4;project++)for(let piece=0;piece<3;piece++){const index=project*3+piece,collected=(adventureState.toyParts[project]||[]).includes(piece),item=part(piece===0?new T.BoxGeometry(1.4,1.4,1.4):piece===1?new T.CylinderGeometry(.7,.7,1.3,12):new T.TorusGeometry(.65,.22,8,14),mat(colors[project],{emissive:colors[project],emissiveIntensity:.65}),cx-235+(index*79)%470,1.2,cz-175+(index*113)%350);item.userData={project,piece,baseY:1.2};item.visible=!collected&&!adventureState.toysBuilt.includes(project);toyQuest.parts.push(item);scene.add(item)}const car=makeVehicle('car',colors[0],cx-145,cz-90,0);car.userData.owned=true;car.userData.price=0;car.userData.toyProject=0;car.visible=adventureState.toysBuilt.includes(0);toyQuest.car=car;const robot=new T.Group();robot.add(part(new T.BoxGeometry(3,4,2),mat(colors[1]),0,3,0),part(new T.BoxGeometry(2.4,2,2),mat(0xdceaf2),0,6,0));[-2,2].forEach(x=>robot.add(part(new T.BoxGeometry(1,4,1),mat(colors[1]),x,3,0)));robot.position.set(cx+145,0,cz-90);scene.add(robot);const train=new T.Group();train.add(part(new T.BoxGeometry(8,3,4),mat(colors[2]),0,2,0),part(new T.BoxGeometry(3,3,3),mat(0x395a49),-2,4,0),part(new T.CylinderGeometry(.55,.75,4,12),mat(0x333333),2,4,0));train.children[2].rotation.z=Math.PI/2;train.position.set(cx-145,0,cz+120);scene.add(train);const rocket=new T.Group();rocket.add(part(new T.CylinderGeometry(1.6,2,7,16),mat(colors[3]),0,4,0),part(new T.ConeGeometry(1.65,3.5,16),mat(0xef5a56),0,9.2,0));[-1,1].forEach(x=>rocket.add(part(new T.BoxGeometry(1.2,3,.5),mat(0xef5a56),x*1.6,2,0)));rocket.position.set(cx+145,0,cz+120);scene.add(rocket);toyQuest.models=[car,robot,train,rocket];toyQuest.models.forEach((m,i)=>m.visible=adventureState.toysBuilt.includes(i))}
function startToyQuest(){flash('🧩 Encontra 3 peças de cada projeto e monta os brinquedos.')}
function collectToyParts(now){if(currentWorld!=='toys'||activeVehicle)return;toyQuest.parts.forEach((item,i)=>{if(!item.visible)return;item.rotation.y+=.035;item.position.y=item.userData.baseY+Math.sin(now*.004+i)*.2;if(Math.hypot(player.position.x-item.position.x,player.position.z-item.position.z)<2.2){item.visible=false;const list=adventureState.toyParts[item.userData.project]??=[];if(!list.includes(item.userData.piece))list.push(item.userData.piece);adventureState.toyParts[item.userData.project]=list;saveAdventures();flash(`🧩 Peça de ${toyNames[item.userData.project]}: ${list.length}/3`);hud()}})}
function nearestToyAction(){if(currentWorld!=='toys'||activeVehicle)return null;let best=null,d=Infinity;toyQuest.pads.forEach(p=>{const n=Math.hypot(player.position.x-p.position.x,player.position.z-p.position.z);if(n<d){best=p;d=n}});return d<7?best:null}
function useToyAction(pad){const project=pad.userData.project,parts=(adventureState.toyParts[project]||[]).length;if(adventureState.toysBuilt.includes(project))return flash(`✅ ${toyNames[project]} já está construído.`);if(parts<3)return flash(`🧩 Ainda faltam ${3-parts} peças de ${toyNames[project]}.`);adventureState.toysBuilt.push(project);toyQuest.models[project].visible=true;coins+=10;const all=adventureState.toysBuilt.length>=4;if(all&&!adventureState.completed['toy-workshop']){adventureState.completed['toy-workshop']=true;coins+=30;typeof celebrate==='function'&&celebrate(true);flash('🏆 Oficina completa: +30 moedas!')}else flash(`🛠️ Construíste ${toyNames[project]}: +10 moedas!`);saveGarage();saveAdventures();hud()}
function updateToyQuest(now){if(currentWorld!=='toys')return;collectToyParts(now);const built=adventureState.toysBuilt||[];if(built.includes(1))toyQuest.models[1].rotation.y=Math.sin(now*.001)*.5;if(built.includes(2)){const a=now*.00035;toyQuest.models[2].position.x=adventureWorlds.toys.x+Math.cos(a)*175;toyQuest.models[2].position.z=adventureWorlds.toys.z+Math.sin(a)*145;toyQuest.models[2].rotation.y=-a+Math.PI/2}if(built.includes(3))toyQuest.models[3].position.y=Math.max(0,Math.sin(now*.00045)*22)}
function makeCastleChallenges(cx,cz){adventureState.castleSolved=Array.isArray(adventureState.castleSolved)?adventureState.castleSolved:[];const spots=[[-120,-105],[120,-105],[-120,135],[120,135]],colors=[0xffd45d,0x62d8c4,0xee7398,0x9b83e2];spots.forEach((p,i)=>{const g=new T.Group(),gate=part(new T.BoxGeometry(10,9,1),mat(adventureState.castleSolved.includes(i)?0x61cc78:colors[i],{emissive:colors[i],emissiveIntensity:.25}),0,4.5,0),orb=part(new T.OctahedronGeometry(1.2),mat(colors[i],{emissive:colors[i],emissiveIntensity:1.2}),0,11,0);g.add(part(new T.BoxGeometry(14,1.2,2),mat(0xe8dfc8),0,9.5,0),part(new T.BoxGeometry(2,10,2),mat(0xe8dfc8),-6,5,0),part(new T.BoxGeometry(2,10,2),mat(0xe8dfc8),6,5,0),gate,orb);g.position.set(cx+p[0],0,cz+p[1]);g.userData={index:i,gate,orb,solved:adventureState.castleSolved.includes(i)};gate.visible=!g.userData.solved;castleQuest.doors.push(g);scene.add(g)})}
function startCastleQuest(){flash('🏰 Resolve os desafios para abrir as quatro portas mágicas.')}
function nearestCastleAction(){if(currentWorld!=='castle'||activeVehicle)return null;let best=null,d=Infinity;castleQuest.doors.forEach(door=>{const n=Math.hypot(player.position.x-door.position.x,player.position.z-door.position.z);if(n<d){best=door;d=n}});return d<7?best:null}
function showCastleQuestion(door){if(door.userData.solved)return flash('✅ Esta porta já está aberta.');const challenge=castleQuest.questions[door.userData.index],box=$('#raceMessage');clearTimeout(flash.timer);box.innerHTML=`<span>🏰✨</span><h2>${challenge.q}</h2><div class="castle-answers">${challenge.a.map((answer,i)=>`<button data-answer="${i}">${answer}</button>`).join('')}</div><button id="castleCancel">AGORA NÃO</button>`;box.classList.remove('hidden');box.querySelectorAll('[data-answer]').forEach(button=>button.onclick=()=>{const correct=Number(button.dataset.answer)===challenge.ok;if(!correct){button.textContent='TENTA OUTRA VEZ';button.classList.add('wrong');typeof tone==='function'&&tone(180,.18);return}door.userData.solved=true;door.userData.gate.visible=false;door.userData.orb.material.color.setHex(0x64df83);adventureState.castleSolved.push(door.userData.index);coins+=8;const all=adventureState.castleSolved.length>=4;if(all&&!adventureState.completed['castle-school']){adventureState.completed['castle-school']=true;coins+=40;typeof celebrate==='function'&&celebrate(true)}saveGarage();saveAdventures();button.textContent=all?'CASTELO COMPLETO!':'PORTA ABERTA!';typeof tone==='function'&&tone(880,.18);setTimeout(()=>{box.classList.add('hidden');hud()},700)});$('#castleCancel').onclick=()=>box.classList.add('hidden')}
function updateCastleQuest(now){if(currentWorld!=='castle')return;castleQuest.doors.forEach((door,i)=>{door.userData.orb.rotation.y+=.025;door.userData.orb.position.y=11+Math.sin(now*.003+i)*.25})}
function makeAdventureWorld(id){const world=adventureWorlds[id],cx=world.x,cz=world.z,theme={dino:{ground:0x507b45,portal:0x74e16f},obby:{ground:0xe5bd67,portal:0xff7a4d},underwater:{ground:0x318fb0,portal:0x50dfff},toys:{ground:0xd6a4dc,portal:0xff69b8},castle:{ground:0x7772b4,portal:0xc998ff}}[id],ground=part(new T.PlaneGeometry(600,500),mat(theme.ground,{roughness:1}),cx,-.1,cz);ground.rotation.x=-Math.PI/2;scene.add(ground);makePortal(cx,cz-220,`${id}-return`,'city',`Regressar da aventura ${world.label}`,theme.portal);if(id==='dino'||id==='castle')for(let i=0;i<34;i++)makeTree(cx-270+(i*83)%540,cz-205+(i*137)%410,.55+(i%3)*.16);if(id!=='obby'&&id!=='dino'&&id!=='underwater'&&id!=='toys'&&id!=='castle'){const spots=[[-185,-115],[170,-95],[-155,125],[185,145]];spots.forEach((p,i)=>makeActivityStation(id,i,cx+p[0],cz+p[1],[0xffd45d,0x62d8c4,0xee7398,theme.portal][i]))}
if(id==='dino'){for(let i=0;i<18;i++)makeDinoFigure(cx-220+(i*53)%440,cz-150+(i*79)%300,[0x58b96b,0xe39a48,0x6fa4d8,0x9b72cf][i%4]);for(let i=0;i<12;i++){const rock=part(new T.DodecahedronGeometry(2+(i%4),0),mat(0x596657),cx-230+(i*97)%460,1.5,cz-175+(i*67)%350);scene.add(rock)}makeDinoRescue(cx,cz)}
if(id==='obby')makeObbyRace(cx,cz)
if(id==='underwater'){for(let i=0;i<95;i++){const coral=part(new T.ConeGeometry(.3+(i%4)*.18,1.4+(i%5)*.7,7),mat([0xff6f91,0xffca58,0x8f79ed,0x56e0be][i%4]),cx-270+(i*47)%540,.8,cz-215+(i*83)%430);scene.add(coral)}for(let i=0;i<24;i++){const bubble=part(new T.SphereGeometry(.3+(i%3)*.15,10,8),new T.MeshBasicMaterial({color:0xdffaff,transparent:true,opacity:.45}),cx-240+(i*31)%480,2+(i%6)*1.5,cz-180+(i*71)%360);scene.add(bubble)}makeSeaMission(cx,cz)}
if(id==='toys'){for(let i=0;i<72;i++){const size=2+(i%5),block=part(new T.BoxGeometry(size,size,size),mat([0xf85f73,0x54c9df,0xffd34f,0x69c86e][i%4]),cx-270+(i*61)%540,size/2,cz-210+(i*89)%420);block.rotation.y=i*.37;scene.add(block)}makeToyWorkshop(cx,cz)}
if(id==='castle'){box(150,12,110,0xd8d2ee,cx,6,cz+40);for(let sx of[-1,1])for(let sz of[-1,1]){const tower=part(new T.CylinderGeometry(13,15,34,12),mat(0x8b83c5),cx+sx*72,17,cz+40+sz*52);scene.add(tower);const roof=part(new T.ConeGeometry(17,13,12),mat(0xe06a8f),cx+sx*72,40,cz+40+sz*52);scene.add(roof)}for(let i=0;i<26;i++){const letter=part(new T.BoxGeometry(5,5,1),mat([0xffd45d,0x62d8c4,0xee7398][i%3]),cx-245+(i*19),2.6,cz+180);scene.add(letter)}makeCastleChallenges(cx,cz)}}
function makeAdventurePortals(){makePortal(150,205,'happy-farm','farm','Fim da estrada para a Quinta',0x72ef9b);makePortal(-150,-205,'dinosaur-cave','dino','Passagem para os Dinossauros',0x76df67);makePortal(205,100,'obstacle-island','obby','Portal dos Obstáculos',0xff7a4d);makePortal(-205,0,'underwater-world','underwater','Porta para o Fundo do Mar',0x50dfff);makePortal(100,-205,'toy-world','toys','Passagem dos Brinquedos',0xff69b8);makePortal(-100,205,'learning-castle','castle','Portal do Castelo Mágico',0xc998ff)}
function nearestPortal(){const target=activeVehicle||player;let best=null,d=Infinity;portals.forEach(p=>{const n=Math.hypot(target.position.x-p.position.x,target.position.z-p.position.z);if(n<d){best=p;d=n}});return d<4.5?best:null}
function crossPortal(){if(performance.now()<portalReadyAt)return;const target=activeVehicle||player,portal=portals.find(p=>Math.hypot(target.position.x-p.position.x,target.position.z-p.position.z)<1.65);if(portal)usePortal(portal)}
function nearestFarmAction(){if(currentWorld!=='farm')return null;const target=activeVehicle||player;let best=null,d=Infinity;if(!activeVehicle){farmPlots.forEach((p,i)=>{const n=Math.hypot(player.position.x-p.position.x,player.position.z-p.position.z);if(n<d){best={type:'plot',object:p,index:i};d=n}});farmAnimals.forEach((a,i)=>{const n=Math.hypot(player.position.x-a.position.x,player.position.z-a.position.z);if(n<d){best={type:'animal',object:a,index:i};d=n}})}farmStations.forEach(s=>{const n=Math.hypot(target.position.x-s.position.x,target.position.z-s.position.z);if(n<d){best={type:s.userData.type,object:s};d=n}});return d<6?best:null}
function usePortal(portal){portalReadyAt=performance.now()+1400;const destination=portal.userData.target;if(currentWorld==='city'&&destination!=='city'&&cityQuest.active){cityQuest.active=null;cityQuest.marker.visible=false}if((destination==='obby'||destination==='dino'||destination==='underwater'||destination==='toys'||destination==='castle')&&activeVehicle&&!activeVehicle.userData.raceKart){activeVehicle.userData.occupied=false;resetRider();activeVehicle=null;player.visible=true}if(destination==='city'&&(activeVehicle?.userData.raceKart||activeVehicle?.userData.toyProject===0)){activeVehicle.userData.occupied=false;resetRider();activeVehicle=null;player.visible=true;obbyRace.running=false}const target=activeVehicle||player;if(destination!=='city'){adventureState.discovered[portal.userData.id]=true;saveAdventures();if(destination==='farm'){farmState.discovered=true;saveFarm()}const world=adventureWorlds[destination];target.position.set(world.x,0,world.z-195);currentWorld=destination;if(destination==='obby')startObbyRace();else if(destination==='dino')startDinoQuest();else if(destination==='underwater')startSeaQuest();else if(destination==='toys')startToyQuest();else if(destination==='castle')startCastleQuest();else flash(`✨ Descobriste: ${world.label}! Procura as atividades pelo mapa.`)}else{const returnPoint=cityPortalReturns[currentWorld]||{x:22,z:18.5};target.position.set(returnPoint.x,0,returnPoint.z);currentWorld='city';flash('🏙️ Regressaste à Cidade das Aventuras.')}heading=destination==='city'?Math.PI:destination==='obby'?Math.PI/2:0;cameraYaw=heading;jumpHeight=jumpVelocity=0;speed=0;if(activeVehicle){activeVehicle.userData.heading=heading;activeVehicle.rotation.y=heading;updateRider(activeVehicle)}hud()}
function useFarmAction(action){const order=farmCrops[farmState.orderIndex];if(action.type==='plot'){let stage=farmState.plots[action.index]||0;stage=stage>=3?0:stage+1;farmState.plots[action.index]=stage;updateFarmPlot(action.object,action.index);const crop=farmCrops[action.object.userData.crop];if(stage===3)flash(`${crop.icon} ${crop.name} pronto para colher!`);else if(stage===0){farmState.harvests++;farmState.produce++;farmState.inventory[crop.id]++;coins+=3;saveGarage();flash(`${crop.icon} Colheste 1 caixa de ${crop.name}: +3 moedas!`)}else flash(stage===1?`🌱 Plantaste ${crop.name}!`:stage===2?'💧 Regaste a plantação!':'🌿 Cuidaste da plantação!')}else if(action.type==='animal'){if(action.object.userData.fed)return flash('✅ Este animal já foi alimentado nesta encomenda.');if(farmState.produce<1)return flash('🌽 Primeiro colhe alimentos para o animal.');const food=farmCrops.find(c=>farmState.inventory[c.id]>0);if(!food)return flash('🧺 Não tens alimentos disponíveis.');farmState.inventory[food.id]--;farmState.produce--;farmState.fed++;farmState.fedAnimals.push(action.index);action.object.userData.fed=true;coins++;saveGarage();flash(`${action.object.userData.label} Comeu ${food.name}: +1 moeda!`)}else if(action.type==='load'){if(activeVehicle?.userData.type!=='tractor')return flash('🚜 Traz o trator para carregar a produção.');if(farmState.cargo>0)return flash('📦 O trator já tem uma encomenda. Entrega-a no mercado.');if(farmState.inventory[order.id]<3)return flash(`${order.icon} O mercado pediu 3 caixas de ${order.name}. Tens ${farmState.inventory[order.id]}.`);farmState.inventory[order.id]-=3;farmState.produce-=3;farmState.cargo=3;farmState.cargoCrop=order.id;flash(`🚜 Carregaste 3 caixas de ${order.name}! Leva-as ao mercado azul.`)}else if(action.type==='market'){if(activeVehicle?.userData.type!=='tractor')return flash('🚜 A entrega tem de chegar no trator.');if(farmState.cargo<3||farmState.cargoCrop!==order.id)return flash(`${order.icon} O mercado espera 3 caixas de ${order.name}.`);farmState.cargo=0;farmState.cargoCrop='';farmState.orders++;farmState.orderIndex=(farmState.orderIndex+1)%farmCrops.length;coins+=18;farmState.fedAnimals=[];farmAnimals.forEach(a=>a.userData.fed=false);saveGarage();typeof celebrate==='function'&&celebrate(true);flash(`🏆 Encomenda de ${order.name} entregue: +18 moedas! Próximo pedido: ${farmCrops[farmState.orderIndex].icon} ${farmCrops[farmState.orderIndex].name}.`)}saveFarm();hud()}
function useCityAction(){if(currentWorld==='obby'){if(obbyRace.finished)startObbyRace();return}const cityJob=nearestCityJob();if(cityJob)return startCityJob(cityJob);const dinoAction=nearestDinoAction();if(dinoAction)return useDinoAction(dinoAction);const seaAction=nearestSeaAction();if(seaAction)return useSeaAction(seaAction);const toyAction=nearestToyAction();if(toyAction)return useToyAction(toyAction);const castleAction=nearestCastleAction();if(castleAction)return showCastleQuestion(castleAction);const farmAction=nearestFarmAction();if(farmAction)return useFarmAction(farmAction);const adventureAction=nearestAdventureAction();if(adventureAction)return useAdventureAction(adventureAction);toggleVehicle()}
function makeRoads(){const roads=[-150,-100,-50,0,50,100,150],ground=part(new T.PlaneGeometry(460,460),mat(0x5fa452,{roughness:1}),0,-.12,0);ground.rotation.x=-Math.PI/2;scene.add(ground);roads.forEach(x=>{box(18,.16,430,0x353a42,x,0,0);for(let z=-205;z<=205;z+=12)box(.22,.025,5,0xe8d36d,x,.1,z)});roads.forEach(z=>{box(430,.16,18,0x353a42,0,.01,z);for(let x=-205;x<=205;x+=12)box(5,.025,.22,0xe8d36d,x,.11,z)});roads.forEach(r=>{for(let t=-188;t<=188;t+=25){if(roads.some(c=>Math.abs(t-c)<14))continue;makeLamp(r-11,t);makeLamp(r+11,t);makeLamp(t,r-11);makeLamp(t,r+11)}})}
function makeCityJobs(){const colors=[0xf0a342,0x55a9e6,0x62bd6d];cityQuest.jobs.forEach((job,i)=>{const npc=makePerson();npc.scale.setScalar(.92);npc.children[0].material=mat(colors[i]);npc.position.set(job.start[0],0,job.start[1]);npc.userData.job=i;const ring=part(new T.TorusGeometry(1.25,.14,8,20),mat(colors[i],{emissive:colors[i],emissiveIntensity:1.2}),job.start[0],3.8,job.start[1]);ring.rotation.x=Math.PI/2;cityQuest.npcs.push(npc);scene.add(npc,ring)});cityQuest.marker=part(new T.TorusGeometry(4,.45,10,24),mat(0xffdc55,{emissive:0xff9d00,emissiveIntensity:1.4}),0,1,0);cityQuest.marker.rotation.x=Math.PI/2;cityQuest.marker.visible=false;scene.add(cityQuest.marker)}
function nearestCityJob(){if(currentWorld!=='city'||cityQuest.active!==null||activeVehicle)return null;let best=null,d=Infinity;cityQuest.npcs.forEach(npc=>{const n=Math.hypot(player.position.x-npc.position.x,player.position.z-npc.position.z);if(n<d){best=npc;d=n}});return d<4.5?best:null}
function startCityJob(npc){const index=npc.userData.job,job=cityQuest.jobs[index];cityQuest.active={index,startedAt:performance.now()};cityQuest.marker.position.set(job.target[0],.3,job.target[1]);cityQuest.marker.visible=true;flash(`${job.icon} ${job.name}: segue o marcador luminoso!`);hud()}
function refreshFarmObjective(){if(currentWorld!=='farm')return;const order=farmCrops[farmState.orderIndex];$('#raceScore').textContent=`🌽 ${farmState.inventory.corn} · 🥕 ${farmState.inventory.carrot} · 🍅 ${farmState.inventory.tomato}`;$('#racePlace').textContent=farmState.cargo?`🚜 Entrega ${farmState.cargo} caixas de ${order.name}`:`📋 Pedido: 3 caixas de ${order.name}`}
function refreshDinoObjective(){if(currentWorld!=='dino')return;$('#raceScore').textContent=`👣 ${dinoQuest.step}/${dinoQuest.footprints.length} · 🥚 ${dinoQuest.eggCount}/${dinoQuest.eggs.length}`;if(dinoQuest.following&&dinoQuest.eggCount<dinoQuest.eggs.length)$('#racePlace').textContent=`🦕 Filhote contigo · faltam ${dinoQuest.eggs.length-dinoQuest.eggCount} ovos`}
function updateCityJob(now){if(currentWorld==='farm'){refreshFarmObjective();return}if(currentWorld==='dino'){refreshDinoObjective();return}if(currentWorld!=='city')return;cityQuest.npcs.forEach((npc,i)=>{npc.rotation.y=Math.sin(now*.0007+i)*.35});if(!cityQuest.active)return;cityQuest.marker.rotation.z+=.025;cityQuest.marker.position.y=.4+Math.sin(now*.004)*.25;const job=cityQuest.jobs[cityQuest.active.index],target=activeVehicle||player;if(Math.hypot(target.position.x-job.target[0],target.position.z-job.target[1])<6){const fast=now-cityQuest.active.startedAt<60000,reward=job.reward+(fast?5:0);coins+=reward;adventureState.cityJobs=(adventureState.cityJobs||0)+1;cityQuest.active=null;cityQuest.marker.visible=false;saveGarage();saveAdventures();typeof celebrate==='function'&&celebrate(true);flash(`✅ Trabalho concluído: +${reward} moedas${fast?' (bónus rápido!)':''}`);hud()}}
function makeCityLife(){const shirtColors=[0xef6c68,0x5d8de3,0xf2b84b,0x8f6bd8,0x42ad87,0xe77fa7],loops=[[[-39,-39],[39,-39],[39,39],[-39,39]],[[-89,-89],[-61,-89],[-61,89],[-89,89]],[[61,-139],[89,-139],[89,139],[61,139]],[[-139,61],[139,61],[139,89],[-139,89]]];for(let i=0;i<12;i++){const route=loops[i%loops.length],person=makePerson(),offset=(i%3)*4;person.scale.setScalar(.82+(i%2)*.08);person.children[0].material=mat(shirtColors[i%shirtColors.length]);person.position.set(route[0][0]+offset,0,route[0][1]+offset);person.userData.cityRoute=route.map(([x,z])=>[x+offset,z+offset]);person.userData.cityPoint=1;person.userData.citySpeed=1.7+(i%4)*.25;person.userData.cityPhase=i*.7;cityLife.people.push(person);scene.add(person)}const trafficColors=[0x3e84d8,0xe25a52,0xf0b83e,0x42a477,0x9a69c7,0xe78942],trafficRoutes=[[[-150,-150],[-150,150],[150,150],[150,-150]],[[-100,-100],[100,-100],[100,100],[-100,100]],[[-50,-150],[50,-150],[50,150],[-50,150]]];for(let i=0;i<6;i++){const route=trafficRoutes[i%trafficRoutes.length],car=new T.Group(),paint=mat(trafficColors[i],{metalness:.25,roughness:.35});car.add(part(new T.BoxGeometry(1.7,.5,3.1),paint,0,.55,0),part(new T.BoxGeometry(1.45,.55,1.5),mat(0x79b7d5,{transparent:true,opacity:.82}),0,1,-.15));[[-.88,-.9],[.88,-.9],[-.88,.95],[.88,.95]].forEach(([x,z])=>car.add(wheel(x,z,.3)));car.position.set(route[0][0]+(i%2?4:-4),0,route[0][1]+(i%2?4:-4));car.userData.cityRoute=route.map(([x,z])=>[x+(i%2?4:-4),z+(i%2?4:-4)]);car.userData.cityPoint=1;car.userData.citySpeed=7+(i%3);cityLife.traffic.push(car);scene.add(car)}}
function moveCityActor(actor,dt,vehicle=false){const route=actor.userData.cityRoute,[tx,tz]=route[actor.userData.cityPoint],dx=tx-actor.position.x,dz=tz-actor.position.z,d=Math.hypot(dx,dz);if(d<1){actor.userData.cityPoint=(actor.userData.cityPoint+1)%route.length;return}const step=Math.min(d,actor.userData.citySpeed*dt),yaw=Math.atan2(dx,dz);actor.position.x+=dx/d*step;actor.position.z+=dz/d*step;actor.rotation.y=yaw;if(vehicle)actor.children.slice(2).forEach(w=>w.rotation.x-=actor.userData.citySpeed*dt/.3);else{const limbs=actor.userData.limbs||[],swing=Math.sin(performance.now()*.009+actor.userData.cityPhase)*.55;if(limbs.length){limbs[0].rotation.x=swing;limbs[1].rotation.x=-swing;limbs[2].rotation.x=-swing;limbs[3].rotation.x=swing}}}
function updateCityLife(dt){if(currentWorld!=='city')return;cityLife.people.forEach(p=>moveCityActor(p,dt));cityLife.traffic.forEach(v=>moveCityActor(v,dt,true))}
function makeCity(){makeRoads();const colors=[0xe09b6b,0x78a8d8,0xd4c178,0xa286c7,0x70b39d,0xc97d89],lots=[-184,-125,-75,-25,25,75,125,184];let i=0;lots.forEach((gx,ix)=>lots.forEach((gz,iz)=>{if((gx===25&&gz===25)||(gx===-25&&gz===25))return;if((ix+iz)%3===0){makeBuilding(gx,gz,23,21,10+(i%4)*4,colors[i++%colors.length])}else{makeHouse(gx+8,gz+7,colors[i++%colors.length]);if((ix+iz)%2)makeHouse(gx-8,gz-7,colors[i%colors.length])}}));const park=part(new T.CylinderGeometry(14,14,.2,40),mat(0x62b968),25,.02,25);scene.add(park);const fountain=part(new T.CylinderGeometry(4.5,5.2,.8,32),mat(0xb8c8cf),25,.4,25);scene.add(fountain);const water=part(new T.CylinderGeometry(4,4,.18,32),mat(0x45b7df,{transparent:true,opacity:.8}),25,.84,25);scene.add(water);for(let a=0;a<Math.PI*2;a+=Math.PI/4)makeTree(25+Math.sin(a)*10.5,25+Math.cos(a)*10.5,.65);lots.forEach((x,ix)=>lots.forEach((z,iz)=>{if((ix*3+iz)%5===0&&!(x===25&&z===25)&&!(x===-25&&z===25))makeTree(x+13,z-13,.65)}));makeDealer();makeVehicle('car',0xe34942,-37,18,Math.PI/2);makeVehicle('motorcycle',0x2384d8,-29,18,Math.PI/2);makeVehicle('scooter',0xf2b632,-21,18,Math.PI/2);makeVehicle('bike',0x47ad66,-13,18,Math.PI/2);for(let i=0;i<30;i++){const c=part(new T.OctahedronGeometry(.5),mat(0xffcf38,{emissive:0xff7b00,emissiveIntensity:1}),-185+(i*71)%370,1,-185+(i*113)%370);c.userData={baseY:1,respawnAt:0};collectibles.push(c);scene.add(c)}makeCityJobs();makeCityLife()}
function blocked(x,z,r=.55){const center=adventureWorlds[currentWorld]||adventureWorlds.city,halfX=currentWorld==='city'?218:292,halfZ=currentWorld==='city'?218:242;if(Math.abs(x-center.x)>halfX||Math.abs(z-center.z)>halfZ)return true;return colliders.some(c=>Math.abs(x-c.x)<c.w/2+r&&Math.abs(z-c.z)<c.d/2+r)}
async function init(){if(ready)return;ready=true;try{T=await import('./assets/three.module.js');renderer=new T.WebGLRenderer({canvas,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;renderer.setClearColor(0x83c8ed);scene=new T.Scene();scene.fog=new T.Fog(0x9ed2eb,180,520);camera=new T.PerspectiveCamera(60,1,.1,5200);scene.add(new T.HemisphereLight(0xe5f5ff,0x455837,2.3));const sun=new T.DirectionalLight(0xffefd0,4);sun.position.set(-70,110,50);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-150;sun.shadow.camera.right=150;sun.shadow.camera.top=150;sun.shadow.camera.bottom=-150;scene.add(sun);makeCity();makeAdventurePortals();makeFarm();['dino','obby','underwater','toys','castle'].forEach(makeAdventureWorld);player=makePerson();const saved=loadSession();if(saved){currentWorld=saved.world;heading=saved.heading;cameraYaw=saved.camera;player.position.set(saved.x,0,saved.z);player.rotation.y=heading}else player.position.set(22,0,18.5);scene.add(player);clock=new T.Clock();setupUi();animate()}catch(e){console.error(e);$('#raceMessage').innerHTML='<h2>Não foi possível abrir a cidade 3D</h2><p>Atualiza a aplicação e tenta novamente.</p>'}}
function setupUi(){if(actionBtn)return;saveGarage();actionBtn=document.createElement('button');actionBtn.id='cityAction';actionBtn.textContent='ENTRAR';document.querySelector('.race-pedals').before(actionBtn);jumpBtn=document.createElement('button');jumpBtn.id='cityJump';jumpBtn.innerHTML='⬆️<small>SALTAR</small>';actionBtn.before(jumpBtn);jumpBtn.onpointerdown=e=>{e.preventDefault();if(!activeVehicle&&jumpHeight<=.02){jumpVelocity=7.4;typeof tone==='function'&&tone(520,.06)}};miniMap=document.createElement('canvas');miniMap.id='cityMiniMap';miniMap.width=240;miniMap.height=240;miniMap.setAttribute('aria-label','Mapa do mundo atual');document.querySelector('.race-hud').after(miniMap);miniCtx=miniMap.getContext('2d');miniMap.onpointerdown=e=>{e.preventDefault();miniMap.classList.toggle('expanded')};modeLabel=document.querySelector('#raceTime');cityLabel=document.querySelector('#raceTime+small');cityLabel.textContent='MODO';actionBtn.onpointerdown=e=>{e.preventDefault();useCityAction()};setupCityJoystick();setupCityCamera()}
function start(){running=true;$('#raceMessage').classList.add('hidden');hud()}
function nearestVehicle(){let best=null,d=Infinity;vehicles.forEach(v=>{if(!v.visible||v.userData.occupied)return;const n=Math.hypot(player.position.x-v.position.x,player.position.z-v.position.z);if(v===lastExited&&n<3.5)return;if(n<d){d=n;best=v}});return best&&d<5.5?best:null}
function resetRider(){player.scale.setScalar(1);player.rotation.z=0;(player.userData.limbs||[]).forEach(l=>l.rotation.set(0,0,0))}
function updateRider(v){if(v.userData.type==='car'||v.userData.type==='tractor'){player.visible=false;return}player.visible=true;const scooter=v.userData.type==='scooter',bike=v.userData.type==='bike';player.scale.setScalar(scooter?.7:.72);player.position.copy(v.position);player.position.y=scooter?.28:bike?.58:.62;player.rotation.set(0,v.userData.heading,0);const l=player.userData.limbs||[];if(l.length){l[0].rotation.x=l[1].rotation.x=scooter?0:-.85;l[2].rotation.x=l[3].rotation.x=scooter?-1.05:-.72;l[2].rotation.z=.12;l[3].rotation.z=-.12}}
function toggleVehicle(){if(activeVehicle){const v=activeVehicle,sideX=Math.cos(v.userData.heading)*2.2,sideZ=-Math.sin(v.userData.heading)*2.2,px=v.position.x+sideX,pz=v.position.z+sideZ;if(blocked(px,pz)){return flash('Não há espaço para sair aqui.')}resetRider();player.position.set(px,0,pz);player.visible=true;v.userData.occupied=false;lastExited=v;activeVehicle=null;speed=0;heading=v.userData.heading;cameraYaw=heading;flash('Saíste do veículo.');hud();return}const v=nearestVehicle();if(!v)return flash('Vai à loja e aproxima-te do veículo que queres.');if(!v.userData.owned){if(coins<v.userData.price)return flash(`Faltam ${v.userData.price-coins} moedas para comprar ${v.userData.name}.`);coins-=v.userData.price;owned.add(v.userData.type);v.userData.owned=true;saveGarage();typeof tone==='function'&&tone(920,.18);flash(`${v.userData.icon} Compraste ${v.userData.name}! Agora toca em ENTRAR.`);hud();return}activeVehicle=v;lastExited=null;v.userData.occupied=true;heading=v.userData.heading;speed=0;updateRider(v);flash(`${v.userData.icon} Entraste: ${v.userData.name}`);hud()}
function flash(text){const box=$('#raceMessage');box.innerHTML=`<p>${text}</p>`;box.classList.remove('hidden');clearTimeout(flash.timer);flash.timer=setTimeout(()=>{if(running)box.classList.add('hidden')},1400)}
function controlAxes(){return input.joystick?{steer:-input.x,throttle:-input.y}:{steer:(input.left?1:0)-(input.right?1:0),throttle:(input.gas?1:0)-(input.reverse?1:0)}}
function walk(dt){const forward=input.joystick?-input.y:(input.gas?1:0)-(input.reverse?1:0),right=input.joystick?-input.x:(input.right?1:0)-(input.left?1:0),power=Math.min(1,Math.hypot(forward,right)),vx=right*Math.cos(cameraYaw)+forward*Math.sin(cameraYaw),vz=-right*Math.sin(cameraYaw)+forward*Math.cos(cameraYaw),pace=4.8+power*2.2,nx=player.position.x+vx*pace*dt,nz=player.position.z+vz*pace*dt;if(power>.06){if(!blocked(nx,nz)){player.position.x=nx;player.position.z=nz}const desired=Math.atan2(vx,vz),delta=(desired-heading+Math.PI*3)%(Math.PI*2)-Math.PI;heading+=delta*Math.min(1,dt*13)}jumpVelocity-=18*dt;jumpHeight=Math.max(0,jumpHeight+jumpVelocity*dt);if(jumpHeight===0&&jumpVelocity<0)jumpVelocity=0;player.position.y=jumpHeight;player.rotation.y=heading;const limbs=player.userData.limbs||[],swing=power>.06?Math.sin(performance.now()*.012)*.7:0;if(limbs.length){limbs[0].rotation.x=swing;limbs[1].rotation.x=-swing;limbs[2].rotation.x=-swing;limbs[3].rotation.x=swing}speed=power*pace}
