function collect(){const target=activeVehicle||player,now=performance.now();collectibles.forEach(c=>{if(!c.visible&&now>=c.userData.respawnAt)c.visible=true;if(!c.visible)return;c.rotation.y+=.035;c.position.y=c.userData.baseY+Math.sin(now*.003+c.position.x)*.18;if(Math.hypot(target.position.x-c.position.x,target.position.z-c.position.z)<2){c.visible=false;c.userData.respawnAt=now+15000;coins++;saveGarage();typeof tone==='function'&&tone(850,.1);hud()}})}
