function animate(){requestAnimationFrame(animate);if(!renderer)return;if(!$('#raceScreen').classList.contains('active')||document.hidden){clock.getDelta();return}const w=canvas.clientWidth||innerWidth,h=canvas.clientHeight||innerHeight,d=Math.min(devicePixelRatio,2);if(canvas.width!==Math.floor(w*d)||canvas.height!==Math.floor(h*d)){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}const dt=Math.min(.04,clock.getDelta()),now=performance.now();portals.forEach((p,i)=>{p.userData.ring.rotation.z=now*.0015+i;p.userData.outer.rotation.z=-now*.0008;p.userData.star.rotation.y=now*.003;p.userData.star.position.y=4.75+Math.sin(now*.004+i)*.18;p.userData.light.material.opacity=.3+Math.sin(now*.004+i)*.14});farmAnimals.forEach((a,i)=>{a.position.y=Math.abs(Math.sin(now*.0025+a.userData.phase))*.08;a.rotation.y+=Math.sin(now*.001+i)*.002});if(running){activeVehicle?drive(dt):walk(dt);updateCityLife(dt);crossPortal();collect();collectAdventure();updateObbyRace(dt);updateDinoQuest(dt,now);updateSeaQuest(dt,now);updateToyQuest(now);updateCastleQuest(now);updateCityJob(now);if(now-lastHud>250){hud();lastHud=now}if(now-lastMap>100){drawMiniMap();lastMap=now}if(now-lastSessionSave>2500){saveSession();lastSessionSave=now}}const target=activeVehicle||player,viewYaw=activeVehicle?heading:cameraYaw,back=activeVehicle?10:7.8,height=(activeVehicle?5.8:4.7)+cameraPitch*5,cam=new T.Vector3(-Math.sin(viewYaw)*back,height,-Math.cos(viewYaw)*back).add(target.position),look=new T.Vector3(Math.sin(viewYaw)*3,activeVehicle?1.2:1.55+cameraPitch*2,Math.cos(viewYaw)*3).add(target.position);camera.position.lerp(cam,.14);camera.lookAt(look);renderer.render(scene,camera)}
function setupCityJoystick(){const steering=$('.race-steering'),pedals=$('.race-pedals');steering.classList.add('legacy-controls');pedals.classList.add('legacy-controls');const joystick=document.createElement('div');joystick.id='cityJoystick';joystick.className='city-joystick';joystick.setAttribute('role','application');joystick.setAttribute('aria-label','Joystick de movimento');joystick.innerHTML='<div class="city-joystick-base"><span class="city-joystick-knob"></span></div><small>MOVER</small>';steering.before(joystick);const base=joystick.querySelector('.city-joystick-base'),knob=joystick.querySelector('.city-joystick-knob');let pointer=null;const paint=(x,y)=>{input.x=x;input.y=y;input.joystick=Math.hypot(x,y)>.06;knob.style.transform=`translate(${x*43}px,${y*43}px)`;joystick.classList.toggle('active',input.joystick)},read=e=>{const r=base.getBoundingClientRect(),radius=r.width*.34,dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,length=Math.hypot(dx,dy),scale=length>radius?radius/length:1;paint(dx*scale/radius,dy*scale/radius)},release=e=>{if(pointer===null||e.pointerId===pointer){pointer=null;paint(0,0)}};base.onpointerdown=e=>{e.preventDefault();pointer=e.pointerId;base.setPointerCapture?.(pointer);read(e)};base.onpointermove=e=>{if(e.pointerId===pointer)read(e)};base.onpointerup=base.onpointercancel=base.onlostpointercapture=release}
function setupCityCamera(){let pointer=null,lastX=0,lastY=0;canvas.onpointerdown=e=>{if(e.clientX<innerWidth*.38)return;pointer=e.pointerId;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture?.(pointer)};canvas.onpointermove=e=>{if(e.pointerId!==pointer||activeVehicle)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;cameraYaw-=dx*.006;cameraPitch=Math.max(-.35,Math.min(.65,cameraPitch-dy*.0045))};const release=e=>{if(e.pointerId===pointer)pointer=null};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=release}
const keys={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'gas',ArrowDown:'reverse'};addEventListener('keydown',e=>{if($('#raceScreen').classList.contains('active')&&keys[e.key]){e.preventDefault();input[keys[e.key]]=true}});addEventListener('keyup',e=>{if(keys[e.key])input[keys[e.key]]=false});addEventListener('visibilitychange',()=>{if(document.hidden)saveSession()});addEventListener('pagehide',saveSession);$('#raceBack').onclick=()=>{saveSession();running=false;Object.keys(input).forEach(k=>input[k]=typeof input[k]==='boolean'?false:0);typeof show==='function'&&show('menuScreen')};window.startDinoRace=()=>{init();const saved=loadSession(),label=saved?adventureWorlds[saved.world].label:'Cidade das Aventuras';$('#raceMessage').innerHTML=`<span>🏙️✨</span><h2>${saved?'Continuar aventura':'Cidade das Aventuras'}</h2><p>${saved?`Vais continuar em <b>${label}</b>, exatamente onde paraste.`:'Explora os finais das estradas e as portas misteriosas. Existem <b>seis portais diferentes</b> para descobrir!'}</p><button id="raceStartNow">${saved?'CONTINUAR':'EXPLORAR'}</button>`;$('#raceMessage').classList.remove('hidden');$('#raceStartNow').onclick=()=>{if(T)start();else setTimeout(()=>$('#raceStartNow')?.click(),250)}};
